/// <summary>
/// Adds a job identification to record after mapping to the entity.
/// </summary>
/// <param name="_sender"><c>TAMRebateAndDeductionsPostingProfileEntity</c> raising the event.</param>
/// <param name="_eventArgs">The arguments of this event.</param>
[DataEventHandler(tableStr(TAMRebateAndDeductionsPostingProfileEntity), DataEventType::MappedEntityToDataSource)]
public static void TAMRebateAndDeductionsPostingProfileEntity_onMappedEntityToDataSource(Common _sender, DataEventArgs _eventArgs)
{
    DataEntityContextEventArgs contextEventArgs = _eventArgs as DataEntityContextEventArgs;
    DataEntityRuntimeContext entityCtx = contextEventArgs.parmEntityContext();
    DataEntityDataSourceRuntimeContext dataSourceCtx = contextEventArgs.parmEntityDataSourceContext();

    if ((entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
        && dataSourceCtx.name() == dataEntityDataSourceStr(TAMRebateAndDeductionsPostingProfileEntity, TAMRebatePosting))
    {
        TAMRebateAndDeductionsPostingProfileEntity rebateAndDeductionsPostingProfileEntity = _sender as TAMRebateAndDeductionsPostingProfileEntity;
        TAMRebatePosting RebatePosting = dataSourceCtx.getBuffer();

        if (rebateAndDeductionsPostingProfileEntity.METFollowTransItemGSTGroup == NoYes::Yes)
        {
            RebatePosting.TaxItemGroup = '';
        }
    }
}
